def clean(df):
    df = df.copy()
    species_map = {'adelie': 'Adelie', 'gentoo': 'Gentoo', 'Gentto': 'Gentoo', 'chinstrap': 'Chinstrap'}
    df['species'] = df['species'].replace(species_map)
    df.loc[df['flipper_length_mm'] < 0, 'flipper_length_mm'] = np.nan
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '').astype(float)
    return df

def answer(df):
    return df.groupby('species')['flipper_length_mm'].mean().to_dict()
